from:
.nav-key { margin-left: auto; font: 500 11px var(--ui); padding: 1px 6px; border-radius: 5px; background: rgba(255, 255, 255, .08); color: var(--soft); opacity: 0; transition: opacity var(--fast); }
.nav-tab:has(.nav-count) .nav-key, .nav-tab:has(.nav-badge:not(.hidden)) .nav-key { margin-left: 8px; }
html.show-hotkeys .nav-key { opacity: 1; }

to:
.nav-key { position: absolute; right: 10px; top: 50%; translate: 0 -50%; font: 500 11px var(--ui); padding: 1px 6px; border-radius: 5px; background: rgba(255, 255, 255, .08); color: var(--soft); opacity: 0; transition: opacity var(--fast); }
.nav-count, .nav-badge { transition: opacity var(--fast); }
html.show-hotkeys .nav-key { opacity: 1; }
/* The hint takes the place of the count rather than pushing it inwards. */
html.show-hotkeys .nav-tab:has(.nav-key) :is(.nav-count, .nav-badge) { opacity: 0; }
